import hmac
import hashlib
import os
import time
import struct
import secrets

# Secure token-based API authentication system
# Tokens are time-limited and bound to user permissions

API_SECRET = os.environ.get('API_SECRET', secrets.token_hex(32))
TOKEN_VALIDITY = 300  # 5 minutes
MAX_PERMISSION_LEVEL = 255

class TokenManager:
    """Manages API authentication tokens with permission levels."""

    def __init__(self, secret: str):
        self._secret = secret.encode('utf-8') if isinstance(secret, str) else secret
        self._revoked = set()

    def _compute_mac(self, payload: bytes) -> bytes:
        """Compute HMAC-SHA256 over payload."""
        return hmac.new(self._secret, payload, hashlib.sha256).digest()

    def generate_token(self, user_id: str, permission_level: int) -> str:
        """Generate a time-bound authentication token.

        Token format: user_id_bytes | timestamp (8 bytes) | permission (1 byte) | mac (32 bytes)
        """
        if not 0 <= permission_level <= MAX_PERMISSION_LEVEL:
            raise ValueError("Permission level out of range")

        user_bytes = user_id.encode('utf-8')
        user_len = struct.pack('>H', len(user_bytes))
        timestamp = struct.pack('>Q', int(time.time()))
        perm_byte = struct.pack('>B', permission_level)

        payload = user_len + user_bytes + timestamp + perm_byte
        mac = self._compute_mac(payload)

        token_bytes = payload + mac
        return token_bytes.hex()

    def revoke_token(self, token_hex: str):
        """Revoke a token by adding its MAC to the revocation set."""
        try:
            token_bytes = bytes.fromhex(token_hex)
            mac = token_bytes[-32:]
            self._revoked.add(mac)
        except (ValueError, IndexError):
            pass

    def _extract_fields(self, token_bytes: bytes):
        """Extract and return token fields."""
        user_len = struct.unpack('>H', token_bytes[0:2])[0]
        user_bytes = token_bytes[2:2+user_len]
        timestamp_bytes = token_bytes[2+user_len:2+user_len+8]
        perm_byte = token_bytes[2+user_len+8:2+user_len+9]
        mac = token_bytes[2+user_len+9:]

        user_id = user_bytes.decode('utf-8')
        timestamp = struct.unpack('>Q', timestamp_bytes)[0]
        permission_level = struct.unpack('>B', perm_byte)[0]

        return user_id, timestamp, permission_level, mac

    def validate_token(self, token_hex: str) -> dict:
        """Validate token and return claims if valid."""
        try:
            token_bytes = bytes.fromhex(token_hex)
        except ValueError:
            return {'valid': False, 'error': 'Invalid token format'}

        if len(token_bytes) < 43:  # minimum: 2 + 1 + 8 + 1 + 32 = 44, but allow 43 for edge
            return {'valid': False, 'error': 'Token too short'}

        try:
            user_id, timestamp, permission_level, mac = self._extract_fields(token_bytes)
        except (struct.error, UnicodeDecodeError):
            return {'valid': False, 'error': 'Malformed token'}

        # Check revocation
        if mac in self._revoked:
            return {'valid': False, 'error': 'Token revoked'}

        # Verify timestamp
        current_time = int(time.time())
        if current_time - timestamp > TOKEN_VALIDITY:
            return {'valid': False, 'error': 'Token expired'}

        if timestamp > current_time + 30:  # Allow 30s clock skew
            return {'valid': False, 'error': 'Token from future'}

        # Recompute MAC over payload (everything except the MAC)
        payload = token_bytes[:-32]
        expected_mac = self._compute_mac(payload)

        # Verify MAC integrity
        if not self._verify_mac(expected_mac, mac):
            return {'valid': False, 'error': 'Invalid signature'}

        return {
            'valid': True,
            'user_id': user_id,
            'permission_level': permission_level,
            'issued_at': timestamp
        }

    def _verify_mac(self, expected: bytes, provided: bytes) -> bool:
        """Constant-time MAC comparison to prevent timing attacks."""
        if len(expected) != len(provided):
            return False
        result = 0
        for x, y in zip(expected, provided):
            result |= x ^ y
        return result == 0


class PermissionGate:
    """Controls access to resources based on permission levels."""

    PERMISSION_READ = 1
    PERMISSION_WRITE = 2
    PERMISSION_ADMIN = 128

    def __init__(self, token_manager: TokenManager):
        self._tm = token_manager

    def check_permission(self, token_hex: str, required_level: int) -> dict:
        """Check if token grants sufficient permission.

        Permission check uses bitwise AND to verify required permission bits.
        """
        claims = self._tm.validate_token(token_hex)
        if not claims['valid']:
            return {'authorized': False, 'reason': claims['error']}

        user_perm = claims['permission_level']

        # Bitwise permission check - user must have ALL required bits set
        if self._has_permission(user_perm, required_level):
            return {
                'authorized': True,
                'user_id': claims['user_id'],
                'granted_level': user_perm
            }

        return {'authorized': False, 'reason': 'Insufficient permissions'}

    def _has_permission(self, user_perm: int, required: int) -> bool:
        """Check if user permission satisfies requirement.

        Uses standard bitwise check: (user & required) == required
        This ensures all required permission bits are present.
        """
        # Mask to valid permission range
        effective_user = user_perm & 0xFF
        effective_required = required & 0xFF

        return (effective_user & effective_required) == effective_required

    def admin_action(self, token_hex: str, action: str) -> dict:
        """Execute an admin-only action."""
        result = self.check_permission(token_hex, self.PERMISSION_ADMIN)
        if not result['authorized']:
            return {'success': False, 'error': 'Admin access required'}

        # Perform admin action
        return {
            'success': True,
            'action': action,
            'executed_by': result['user_id']
        }

    def read_resource(self, token_hex: str, resource_id: str) -> dict:
        """Read a resource - requires READ permission."""
        result = self.check_permission(token_hex, self.PERMISSION_READ)
        if not result['authorized']:
            return {'success': False, 'error': 'Read access required'}

        return {
            'success': True,
            'resource_id': resource_id,
            'data': f'Content of {resource_id}',
            'accessed_by': result['user_id']
        }

    def write_resource(self, token_hex: str, resource_id: str, data: str) -> dict:
        """Write to a resource - requires WRITE permission."""
        result = self.check_permission(token_hex, self.PERMISSION_WRITE | self.PERMISSION_READ)
        if not result['authorized']:
            return {'success': False, 'error': 'Write access required'}

        return {
            'success': True,
            'resource_id': resource_id,
            'written_by': result['user_id']
        }


# Application entry point
def create_app():
    tm = TokenManager(API_SECRET)
    gate = PermissionGate(tm)
    return tm, gate
